  for(i=0;i<elcount(TxMessageId);i++)
  {
    TestJoinMessageEvent(TxMessageId[i]);
  } 
  index=TestWaitForAnyJoinedEvent(10000);
  Eventtime = TestGetLastWaitElapsedTimeNS()/1000000;
  if(index==0)
  {
    testStepFail("初始化时间","10s内未检测到ECU发送报文");
  }
  else
  {
    if(Eventtime <=Time)
      {
        testStepPass("初始化时间","初始化时间%dms,实际时间 %g",Time,Eventtime);
      }
    if(Eventtime >Time)
      {
        testStepFail("初始化时间","初始化时间%dms,实际时间 %g",Time,Eventtime);
      }      
  }
}
/// <Check>
void Check_Interval_time(long Time)
{
  dword index = 0;
  float Eventtime,longtime;
  int i;
  longtime=TimeNowNS()/1000000;
  Eventtime = 10;
  while(TimeNowNS()/1000000-longtime < 1000)
  {
    for(i=0;i<elcount(TxMessageId);i++)
    {
      TestJoinMessageEvent(TxMessageId[i]);
    }     
    index=TestWaitForAnyJoinedEvent(10000);
    Eventtime=_min(TestGetLastWaitElapsedTimeNS()/1000000,Eventtime);    
  }
  if(index==0)
  {
    testStepFail("间隔时间","10s内未检测到ECU发送报文");
  }
  else
  {
    if(Eventtime >=Time)
      {
        testStepPass("间隔时间","最小间隔时间%dms,实际时间 %g",Time,Eventtime);
      }
    if(Eventtime <Time)
      {
        testStepFail("间隔时间","最小间隔时间%dms,实际时间 %g",Time,Eventtime);
      }      
  }
}
/// <Check>
void Check_TxStop_time(long minTime,long maxTime)
{
  float timenow,timenow1;
  int i;
  timenow=TimeNowNS()/1000000;
  while(1)
  {
    for(i=0;i<elcount(TxMessageId);i++)
    {
      TestJoinMessageEvent(TxMessageId[i]);
    }
    if(testWaitForAnyJoinedEvent(2000) == 0 || timenow1 > 5000)
    {break;}

    timenow1=TimeNowNS()/1000000-timenow;
  }
  if(timenow1 <= maxTime && timenow1 >= minTime)
    {
      testStepPass("通信停止时间","通信停止时间[%dms,%dms],实际时间 %g",minTime,maxTime,timenow1);
    }
  if(timenow1 > maxTime || timenow1 < minTime)
    {
      testStepFail("通信停止时间","通信停止时间[%dms,%dms],实际时间 %g",minTime,maxTime,timenow1);
    }      

}
